1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"hash/crc32"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12	)
13	
14	// Incremental backup chains.
15	//
16	// A full Backup artifact is the head of a backup chain: its manifest fixes the
17	// head watermark and the head content hash. BackupIncremental appends one
18	// self-describing ring to the chain directory, covering only the terminal
19	// state of keys touched between the previous ring's watermark and a fresh
20	// fixed anchor; Restore synthesizes the rings over the head in chain order to
21	// rebuild the state at the last ring's watermark.
22	//
23	// Chain layout, inside the chain directory (alongside the head files):
24	//
25	//	incr.tmp/                  staging area while an incremental export runs
26	//	incr-0000000001.dat        first ring, appended after the head
27	//	incr-0000000002.dat        second ring, and so on
28	//
29	// Rings are indexed from 1, dense, and link backwards by content hash: ring 1
30	// links to the head manifest's terminal CRC; ring k links to ring k-1's
31	// terminal file CRC. A ring also names the exact watermark it starts from
32	// (the previous ring's end watermark; the head watermark for ring 1). The
33	// chain is therefore complete if and only if the head artifact is intact and
34	// every dense ring is present, whole, checksum-good, of a known version,
35	// linked to its predecessor and watermark-continuous with it. Restore
36	// validates the whole chain before building anything and rejects the entire
37	// directory with fs.ErrInvalid on the first defect; half a chain is never
38	// installed.
39	//
40	// A ring is promoted with a hard link from its staging file: link(2) fails if
41	// the final name already exists, so a ring is either wholly present under its
42	// final name or absent — a kill at any instant never leaves a truncated ring
43	// and two concurrent exports can never clobber one ring.
44	//
45	// Ring file layout (all integers little-endian):
46	//
47	//	header:
48	//	magic      uint32   backupMagic
49	//	version    uint32   backupVersion (one format with the head)
50	//	ringIndex  uint32   1-based position on the chain
51	//	prevLink   uint32   content CRC of the previous artifact (manifest/ring)
52	//	startWM    uint64   watermark this ring starts from (exclusive)
53	//	endWM      uint64   anchor watermark this ring ends at (inclusive)
54	//	snapshots  uint64   cumulative snapshot count at endWM
55	//	segCount   uint32   number of segments that follow (0 for an empty ring)
56	//
57	//	segments[segCount]:
58	//	  magic      uint32   backupMagic
59	//	  startWM    uint64
60	//	  endWM      uint64
61	//	  ringIndex  uint32
62	//	  segIndex   uint32   0-based within the ring
63	//	  count      uint32   entries in this segment (always > 0)
64	//	  cumulative uint64   cumulative live-entry count through this segment
65	//	  entries    [count] entry, same encoding as head segments
66	//	  segCRC     uint32   IEEE CRC-32 of every preceding byte of the segment
67	//
68	//	footer:
69	//	total       uint64   total entry count across segments
70	//	segCount    uint32   repeated for cross-checking
71	//	segChainCRC uint32   chained CRC-32 over the segments' terminal CRCs
72	//	fileCRC     uint32   IEEE CRC-32 of every preceding byte of the file
73	//
74	// Entries are strictly key-ascending and unique inside one ring. Every entry
75	// sequence lies in (startWM, endWM]: it is the terminal commit sequence the
76	// anchored view shows. The sole exception is a tombstone synthesized for a
77	// key the chain once held but a compaction has since forgotten entirely: its
78	// delete cannot be read back from memory, so the ring records the key with
79	// the anchor watermark endWM as its ordering marker. Synthesis re-sequences
80	// every frame densely anyway, so the terminal state is exact regardless.
81	//
82	// An empty ring (no touched keys, segCount 0, endWM == startWM) is legal: it
83	// still moves the chain's snapshot count forward. Any non-empty ring has
84	// endWM > startWM.
85	const (
86		incrStageDir    = "incr.tmp"
87		incrPrefix      = "incr-"
88		incrSuffix      = ".dat"
89		incrIndexDigits = 10
90	
91		incrRingHeaderSize = 4 + 4 + 4 + 4 + 8 + 8 + 8 + 4
92		incrSegHeaderSize  = 4 + 8 + 8 + 4 + 4 + 4 + 8
93		incrFooterSize     = 8 + 4 + 4 + 4
94	)
95	
96	// ringExpect pins what a ring must link to when it is read as part of a
97	// specific chain.
98	type ringExpect struct {
99		index    uint32 // required ring index
100		prevLink uint32 // required predecessor content CRC
101		startWM  uint64 // required start watermark
102	}
103	
104	// ringSummary is what a validated ring establishes for the chain after it.
105	type ringSummary struct {
106		index    uint32
107		endWM    uint64
108		snaps    uint64
109		total    uint64
110		fileCRC  uint32
111		segCount uint32
112	}
113	
114	// ringName renders a 1-based ring index as a fixed-width file name.
115	func ringName(index uint32) string {
116		const digits = "0123456789"
117		buf := make([]byte, incrIndexDigits)
118		n := index
119		for i := len(buf) - 1; i >= 0; i-- {
120			buf[i] = digits[n%10]
121			n /= 10
122		}
123		return incrPrefix + string(buf) + incrSuffix
124	}
125	
126	// parseRingIndex is the inverse of ringName. ok is false for names that are
127	// not well-formed finished ring files.
128	func parseRingIndex(name string) (uint32, bool) {
129		mid := len(incrPrefix) + incrIndexDigits
130		if len(name) != mid+len(incrSuffix) ||
131			name[:len(incrPrefix)] != incrPrefix ||
132			name[mid:] != incrSuffix {
133			return 0, false
134		}
135		var n uint32
136		for i := len(incrPrefix); i < mid; i++ {
137			c := name[i]
138			if c < '0' || c > '9' {
139				return 0, false
140			}
141			n = n*10 + uint32(c-'0')
142		}
143		if n == 0 {
144			return 0, false // rings are 1-based
145		}
146		return n, true
147	}
148	
149	// ringEntryCallback observes one entry while a ring is streamed.
150	type ringEntryCallback func(flag byte, key string, value []byte, seq uint64) error
151	
152	// scanRing streams one open ring file, validating every byte of it and
153	// checking linkage against exp, and hands each entry to cb (which may be
154	// nil). Nothing beyond the entry currently being read is held in memory.
155	func scanRing(f *os.File, exp ringExpect, cb ringEntryCallback) (ringSummary, error) {
156		var zero ringSummary
157		r := bufio.NewReader(f)
158		hf := crc32.NewIEEE()
159	
160		read := func(buf []byte) error {
161			if err := readFull(r, buf); err != nil {
162				return err
163			}
164			hf.Write(buf)
165			return nil
166		}
167	
168		head := make([]byte, incrRingHeaderSize)
169		if err := read(head); err != nil {
170			return zero, err
171		}
172		if binary.LittleEndian.Uint32(head[0:4]) != backupMagic ||
173			binary.LittleEndian.Uint32(head[4:8]) != backupVersion {
174			return zero, errBadBackup
175		}
176		index := binary.LittleEndian.Uint32(head[8:12])
177		prevLink := binary.LittleEndian.Uint32(head[12:16])
178		startWM := binary.LittleEndian.Uint64(head[16:24])
179		endWM := binary.LittleEndian.Uint64(head[24:32])
180		snaps := binary.LittleEndian.Uint64(head[32:40])
181		segCount := binary.LittleEndian.Uint32(head[40:44])
182		if index != exp.index || prevLink != exp.prevLink || startWM != exp.startWM ||
183			endWM < startWM || segCount > backupMaxSegments {
184			return zero, errBadBackup
185		}
186	
187		ehdr := make([]byte, checkpointEntrySize)
188		shdr := make([]byte, incrSegHeaderSize)
189		var crcb [crcSize]byte
190		var cumulative, total uint64
191		var segChain uint32
192		var lastKey string
193		haveKey := false
194	
195		for seg := uint32(0); seg < segCount; seg++ {
196			if err := read(shdr); err != nil {
197				return zero, err
198			}
199			hs := crc32.NewIEEE()
200			hs.Write(shdr)
201			if binary.LittleEndian.Uint32(shdr[0:4]) != backupMagic ||
202				binary.LittleEndian.Uint64(shdr[4:12]) != startWM ||
203				binary.LittleEndian.Uint64(shdr[12:20]) != endWM ||
204				binary.LittleEndian.Uint32(shdr[20:24]) != index ||
205				binary.LittleEndian.Uint32(shdr[24:28]) != seg {
206				return zero, errBadBackup
207			}
208			count := binary.LittleEndian.Uint32(shdr[28:32])
209			segCum := binary.LittleEndian.Uint64(shdr[32:40])
210			if count == 0 || count > maxRecord {
211				return zero, errBadBackup
212			}
213			for i := uint32(0); i < count; i++ {
214				if err := read(ehdr); err != nil {
215					return zero, err
216				}
217				hs.Write(ehdr)
218				flag := ehdr[0]
219				keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
220				valLen := binary.LittleEndian.Uint32(ehdr[5:9])
221				seq := binary.LittleEndian.Uint64(ehdr[9:17])
222				if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
223					keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
224					(flag == ckptFlagDelete && valLen != 0) ||
225					seq <= startWM || seq > endWM {
226					return zero, errBadBackup
227				}
228				body := make([]byte, int(keyLen)+int(valLen))
229				if err := read(body); err != nil {
230					return zero, err
231				}
232				hs.Write(body)
233				key := string(body[:keyLen])
234				if haveKey && key <= lastKey {
235					return zero, errBadBackup
236				}
237				lastKey, haveKey = key, true
238				if cb != nil {
239					if err := cb(flag, key, body[keyLen:], seq); err != nil {
240						return zero, err
241					}
242				}
243			}
244			if err := read(crcb[:]); err != nil {
245				return zero, err
246			}
247			if binary.LittleEndian.Uint32(crcb[:]) != hs.Sum32() {
248				return zero, errBadBackup
249			}
250			segChain = crc32.Update(segChain, crc32.IEEETable, crcb[:])
251			cumulative += uint64(count)
252			if segCum != cumulative {
253				return zero, errBadBackup
254			}
255			total = cumulative
256		}
257	
258		foot := make([]byte, incrFooterSize)
259		if err := read(foot); err != nil {
260			return zero, err
261		}
262		if binary.LittleEndian.Uint64(foot[0:8]) != total ||
263			binary.LittleEndian.Uint32(foot[8:12]) != segCount ||
264			binary.LittleEndian.Uint32(foot[12:16]) != segChain {
265			return zero, errBadBackup
266		}
267		// The terminal file CRC covers every preceding byte; it is not part of its
268		// own input.
269		var terminal [crcSize]byte
270		if err := readFull(r, terminal[:]); err != nil {
271			return zero, err
272		}
273		if binary.LittleEndian.Uint32(terminal[:]) != hf.Sum32() {
274			return zero, errBadBackup
275		}
276		if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
277			return zero, errBadBackup
278		}
279	
280		if total > 0 && endWM == startWM {
281			return zero, errBadBackup
282		}
283		return ringSummary{
284			index:    index,
285			endWM:    endWM,
286			snaps:    snaps,
287			total:    total,
288			fileCRC:  binary.LittleEndian.Uint32(terminal[:]),
289			segCount: segCount,
290		}, nil
291	}
292	
293	// streamHeadSegments validates and streams every head segment named by the
294	// manifest, in order, handing each put entry to cb. The head manifest is
295	// trusted to already have been validated.
296	func streamHeadSegments(backupDir string, head manifestInfo, cb ringEntryCallback) error {
297		var lastKey string
298		haveKey := false
299		var seen uint64
300		for _, seg := range head.segments {
301			f, err := os.Open(filepath.Join(backupDir, segmentName(seg.index)))
302			if err != nil {
303				return err
304			}
305			r := bufio.NewReader(f)
306			hdr := make([]byte, backupSegHeaderSize)
307			if err := readFull(r, hdr); err != nil {
308				f.Close()
309				return err
310			}
311			h := crc32.NewIEEE()
312			h.Write(hdr)
313			magic := binary.LittleEndian.Uint32(hdr[0:4])
314			version := binary.LittleEndian.Uint32(hdr[4:8])
315			watermark := binary.LittleEndian.Uint64(hdr[8:16])
316			snaps := binary.LittleEndian.Uint64(hdr[16:24])
317			index := binary.LittleEndian.Uint32(hdr[24:28])
318			count := binary.LittleEndian.Uint32(hdr[28:32])
319			cumulative := binary.LittleEndian.Uint64(hdr[32:40])
320			if magic != backupMagic || version != backupVersion ||
321				watermark != head.watermark || snaps != head.snaps ||
322				index != seg.index || count != seg.count || cumulative != seg.cumulative {
323				f.Close()
324				return errBadBackup
325			}
326			ehdr := make([]byte, checkpointEntrySize)
327			for i := uint32(0); i < count; i++ {
328				if err := readFull(r, ehdr); err != nil {
329					f.Close()
330					return err
331				}
332				h.Write(ehdr)
333				flag := ehdr[0]
334				keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
335				valLen := binary.LittleEndian.Uint32(ehdr[5:9])
336				seq := binary.LittleEndian.Uint64(ehdr[9:17])
337				if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
338					keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
339					(flag == ckptFlagDelete && valLen != 0) ||
340					seq == 0 || seq > watermark {
341					f.Close()
342					return errBadBackup
343				}
344				body := make([]byte, int(keyLen)+int(valLen))
345				if err := readFull(r, body); err != nil {
346					f.Close()
347					return err
348				}
349				h.Write(body)
350				key := string(body[:keyLen])
351				if haveKey && key <= lastKey {
352					f.Close()
353					return errBadBackup
354				}
355				lastKey, haveKey = key, true
356				if cb != nil {
357					if err := cb(flag, key, body[keyLen:], seq); err != nil {
358						f.Close()
359						return err
360					}
361				}
362			}
363			var crcb [crcSize]byte
364			if err := readFull(r, crcb[:]); err != nil {
365				f.Close()
366				return err
367			}
368			if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() ||
369				binary.LittleEndian.Uint32(crcb[:]) != seg.crc {
370				f.Close()
371				return errBadBackup
372			}
373			if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
374				f.Close()
375				return errBadBackup
376			}
377			f.Close()
378			seen += uint64(count)
379		}
380		if seen != head.total {
381			return errBadBackup
382		}
383		return nil
384	}
385	
386	// artifactInfo is a fully validated backup chain directory.
387	type artifactInfo struct {
388		head      manifestInfo
389		ringCount uint32 // number of rings dense after the head
390		tipCRC    uint32 // content CRC the next ring must link to
391		endWM     uint64 // watermark of the chain tip
392		snaps     uint64 // cumulative snapshot count at the chain tip
393	}
394	
395	// validateBackupChain inspects backupDir as one whole chain: the head
396	// manifest, an exact dense head segment set and dense linked rings with
397	// continuous watermarks. It streams every file and holds no entry content.
398	// Any defect returns an error wrapping fs.ErrInvalid; genuine read failures
399	// pass through unchanged.
400	func validateBackupChain(backupDir string) (artifactInfo, error) {
401		var zero artifactInfo
402		head, err := loadBackupManifest(backupDir)
403		if err != nil {
404			return zero, err
405		}
406	
407		entries, err := os.ReadDir(backupDir)
408		if err != nil {
409			return zero, err
410		}
411		headSegs := make(map[uint32]bool, len(head.segments))
412		for _, s := range head.segments {
413			headSegs[s.index] = true
414		}
415		ringSet := make(map[uint32]bool)
416		sawManifest := false
417		for _, e := range entries {
418			name := e.Name()
419			if e.IsDir() {
420				return zero, errBadBackup // no staging or foreign directory in an artifact
421			}
422			switch {
423			case name == backupManifest:
424				sawManifest = true
425			case name == backupManifestTmp:
426				return zero, errBadBackup
427			default:
428				if idx, ok := parseSegmentIndex(name); ok {
429					if !headSegs[idx] {
430						return zero, errBadBackup
431					}
432					headSegs[idx] = false // mark present
433					continue
434				}
435				if idx, ok := parseRingIndex(name); ok {
436					if ringSet[idx] {
437						return zero, errBadBackup
438					}
439					ringSet[idx] = true
440					continue
441				}
442				return zero, errBadBackup // foreign file
443			}
444		}
445		if !sawManifest {
446			return zero, errBadBackup
447		}
448		for idx, missing := range headSegs {
449			if missing {
450				_ = idx
451				return zero, errBadBackup // a manifest-named segment is absent
452			}
453		}
454	
455		// Deep-validate the head segments before trusting any of the chain.
456		if err := streamHeadSegments(backupDir, head, nil); err != nil {
457			return zero, err
458		}
459	
460		// Validate the dense ring sequence and its linkage.
461		ringCount := uint32(len(ringSet))
462		for idx := uint32(1); idx <= ringCount; idx++ {
463			if !ringSet[idx] {
464				return zero, errBadBackup // gap in the rings
465			}
466		}
467		prevWM := head.watermark
468		prevSnaps := head.snaps
469		prevLink := head.crc
470		tipCRC := head.crc
471		for idx := uint32(1); idx <= ringCount; idx++ {
472			f, oerr := os.Open(filepath.Join(backupDir, ringName(idx)))
473			if oerr != nil {
474				return zero, oerr
475			}
476			sum, serr := scanRing(f, ringExpect{
477				index:    idx,
478				prevLink: prevLink,
479				startWM:  prevWM,
480			}, nil)
481			f.Close()
482			if serr != nil {
483				return zero, serr
484			}
485			if sum.snaps < prevSnaps {
486				return zero, errBadBackup
487			}
488			prevWM = sum.endWM
489			prevSnaps = sum.snaps
490			prevLink = sum.fileCRC
491			tipCRC = sum.fileCRC
492		}
493		return artifactInfo{
494			head:      head,
495			ringCount: ringCount,
496			tipCRC:    tipCRC,
497			endWM:     prevWM,
498			snaps:     prevSnaps,
499		}, nil
500	}
501	
502	// dirHasRings reports whether backupDir names at least one finished ring
503	// file. Its only read error passes through from the directory listing.
504	func dirHasRings(backupDir string) (bool, error) {
505		entries, err := os.ReadDir(backupDir)
506		if err != nil {
507			return false, err
508		}
509		for _, e := range entries {
510			if !e.IsDir() {
511				if _, ok := parseRingIndex(e.Name()); ok {
512					return true, nil
513				}
514			}
515		}
516		return false, nil
517	}
518	
519	// buildChainRestoredStore streams a validated head-plus-rings chain into a
520	// fresh wal.log in the staging directory, applying the artifacts in chain
521	// order (each ring overriding the one before) so the result is exactly the
522	// terminal state at the chain tip. It streams one entry at a time and keeps
523	// no keyspace in memory.
524	//
525	// Frames are re-sequenced densely in application order: a key's own frames
526	// are encountered head-before-ring and in ring order, so its per-key sequence
527	// keeps increasing; replay therefore links the same terminal the chain
528	// computes. The snapshot count at the tip is appended as the closing meta,
529	// the same compacted-log shape buildRestoredStore writes. Nothing is
530	// installed until this whole step succeeds.
531	func buildChainRestoredStore(stage, backupDir string, art artifactInfo) error {
532		wf, err := os.OpenFile(filepath.Join(stage, walName), os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
533		if err != nil {
534			return err
535		}
536		fail := func(err error) error {
537			wf.Close()
538			return err
539		}
540		l := &walWriter{f: wf, w: bufio.NewWriter(wf)}
541		var seq uint64
542	
543		apply := func(flag byte, key string, value []byte, _ uint64) error {
544			seq++
545			if flag == ckptFlagPut {
546				return l.encodeFrameSeq(opPutSeq, key, seq, value)
547			}
548			return l.encodeFrameSeq(opDeleteSeq, key, seq, nil)
549		}
550	
551		if err := streamHeadSegments(backupDir, art.head, apply); err != nil {
552			return fail(err)
553		}
554		prevWM := art.head.watermark
555		prevLink := art.head.crc
556		for idx := uint32(1); idx <= art.ringCount; idx++ {
557			f, oerr := os.Open(filepath.Join(backupDir, ringName(idx)))
558			if oerr != nil {
559				return fail(oerr)
560			}
561			sum, serr := scanRing(f, ringExpect{
562				index:    idx,
563				prevLink: prevLink,
564				startWM:  prevWM,
565			}, apply)
566			f.Close()
567			if serr != nil {
568				return fail(serr)
569			}
570			prevWM = sum.endWM
571			prevLink = sum.fileCRC
572		}
573	
574		if art.snaps > 0 {
575			var v [metaValueSize]byte
576			binary.LittleEndian.PutUint64(v[:], art.snaps)
577			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
578				return fail(err)
579			}
580		}
581		if err := l.w.Flush(); err != nil {
582			return fail(err)
583		}
584		if err := wf.Sync(); err != nil {
585			return fail(err)
586		}
587		if err := wf.Close(); err != nil {
588			return err
589		}
590		return syncDirectory(stage)
591	}
592	
593	// presentSetAtTip streams the whole validated chain and returns the set of
594	// keys present at its tip. It is one set of live keys (bounded by live data,
595	// never by the chain length), not a copy of any value: the next incremental
596	// export needs exactly this set to tell an untouched key from one touched,
597	// deleted and then forgotten by compaction.
598	func presentSetAtTip(backupDir string, art artifactInfo) (map[string]struct{}, error) {
599		present := make(map[string]struct{})
600		add := func(flag byte, key string, _ []byte, _ uint64) error {
601			if flag == ckptFlagPut {
602				present[key] = struct{}{}
603			} else {
604				delete(present, key)
605			}
606			return nil
607		}
608		if err := streamHeadSegments(backupDir, art.head, add); err != nil {
609			return nil, err
610		}
611		prevWM := art.head.watermark
612		prevLink := art.head.crc
613		for idx := uint32(1); idx <= art.ringCount; idx++ {
614			f, err := os.Open(filepath.Join(backupDir, ringName(idx)))
615			if err != nil {
616				return nil, err
617			}
618			sum, serr := scanRing(f, ringExpect{
619				index:    idx,
620				prevLink: prevLink,
621				startWM:  prevWM,
622			}, add)
623			f.Close()
624			if serr != nil {
625				return nil, serr
626			}
627			prevWM = sum.endWM
628			prevLink = sum.fileCRC
629		}
630		return present, nil
631	}
632	
633	// ringEntryKind marks one touched key's terminal state for a new ring.
634	type ringEntryKind struct {
635		key    string
636		seq    uint64
637		delete bool
638	}
639	
640	// BackupIncremental appends one incremental ring to the backup chain in
641	// chainDir, anchored at the commit watermark current when it anchors. The
642	// chain directory must already hold a complete full backup (the chain head);
643	// writes and deletes committed after the anchor do not enter the ring, while
644	// the foreground keeps committing.
645	//
646	// The ring holds only the terminal state of keys touched between the chain
647	// tip's watermark and the anchor: later puts overwrite earlier ones, and keys
648	// deleted in the interval are recorded as tombstones and read back as misses
649	// after synthesis. Keys the compaction has forgotten entirely but the chain
650	// once held are recorded as tombstones too, so a delete is never resurrected
651	// by a later compaction of the backed-up store.
652	//
653	// The ring is streamed in bounded chunks and installed all-or-nothing under
654	// a staging name: a kill at any instant leaves the chain exactly as it was
655	// (staging debris is swept at the next export into, or Open of, the
656	// directory), and the backed-up store is never modified.
657	//
658	// A chain directory that is missing, not a directory, incomplete or damaged
659	// (a missing ring, a broken link, a non-continuous watermark, truncation,
660	// checksum failure or unknown version), or a chain advanced concurrently
661	// during the export, rejects the whole operation with an error wrapping
662	// fs.ErrInvalid and leaves no partial ring. BackupIncremental on a closed
663	// store returns an error wrapping fs.ErrClosed.
664	func (s *Store) BackupIncremental(chainDir string) error {
665		if s.closed.Load() {
666			return errStoreClosed
667		}
668		// Serialize exports driven by one store so they can never share a staging
669		// directory or race to append the same ring index. This does not serialize
670		// with commits or reads.
671		s.backupMu.Lock()
672		defer s.backupMu.Unlock()
673		if s.closed.Load() {
674			return errStoreClosed
675		}
676		if chainDir == "" {
677			return errBadBackup
678		}
679		info, err := os.Stat(chainDir)
680		if err != nil {
681			if errors.Is(err, os.ErrNotExist) {
682				return errBadBackup
683			}
684			return err
685		}
686		if !info.IsDir() {
687			return errBadBackup
688		}
689		// Clear staging debris from an export (full or incremental) killed mid-run
690		// before inspecting the chain; a manifest temp is pure debris as well.
691		for _, stage := range []string{incrStageDir, backupStageDir} {
692			if err := os.RemoveAll(filepath.Join(chainDir, stage)); err != nil {
693				return err
694			}
695		}
696		if err := os.Remove(filepath.Join(chainDir, backupManifestTmp)); err != nil &&
697			!errors.Is(err, os.ErrNotExist) {
698			return err
699		}
700	
701		art, err := validateBackupChain(chainDir)
702		if err != nil {
703			return err
704		}
705		// The chain tip's present-key set is the baseline the touched set is
706		// diffed against. Streamed from immutable artifacts, it needs no lock.
707		prevPresent, err := presentSetAtTip(chainDir, art)
708		if err != nil {
709			return err
710		}
711	
712		// Anchor at one fixed watermark. This is the only moment the export takes
713		// the write lock; entry resolution and streaming run on the immutable
714		// anchored view without it.
715		s.mu.Lock()
716		if s.closed.Load() {
717			s.mu.Unlock()
718			return errStoreClosed
719		}
720		anchor := backupAnchor{
721			view:      s.current.Load(),
722			watermark: s.nextSeq,
723			snaps:     s.snapshots.Load(),
724		}
725		s.mu.Unlock()
726	
727		startWM := art.endWM
728		// The anchor must be a continuation of the chain: a watermark or snapshot
729		// count behind the tip means this store cannot extend that chain, so the
730		// export is rejected wholesale before any ring file is staged.
731		if anchor.watermark < startWM || anchor.snaps < art.snaps {
732			return errBadBackup
733		}
734		touched := collectTouchedKeys(anchor.view, prevPresent, startWM, anchor.watermark)
735	
736		index := art.ringCount + 1
737		return writeIncrementalRing(chainDir, ringHeader{
738			index:    index,
739			prevLink: art.tipCRC,
740			startWM:  startWM,
741			endWM:    anchor.watermark,
742			snaps:    anchor.snaps,
743		}, anchor, touched)
744	}
745	
746	// ringHeader carries the fixed fields of a ring being written.
747	type ringHeader struct {
748		index    uint32
749		prevLink uint32
750		startWM  uint64
751		endWM    uint64
752		snaps    uint64
753	}
754	
755	// collectTouchedKeys diffs the anchored view against the present-key set the
756	// chain held at startWM and returns the touched keys' terminal state, sorted
757	// by key. A key present in the chain but absent from the view was deleted and
758	// forgotten by compaction; it still enters the ring as a tombstone, stamped
759	// at the anchor watermark.
760	func collectTouchedKeys(v *view, prevPresent map[string]struct{}, startWM, endWM uint64) []ringEntryKind {
761		var touched []ringEntryKind
762		seen := make(map[string]struct{}, len(prevPresent))
763		v.rangeEach(func(k string, n *node) bool {
764			seen[k] = struct{}{}
765			_, was := prevPresent[k]
766			if n.present {
767				if !was || n.seq > startWM {
768					touched = append(touched, ringEntryKind{key: k, seq: n.seq})
769				}
770			} else if was {
771				touched = append(touched, ringEntryKind{key: k, seq: n.seq, delete: true})
772			}
773			return true
774		})
775		// Keys the chain knew but the view no longer even mentions: deleted and
776		// dropped by a compaction. Stamp the tombstone at the anchor.
777		for k := range prevPresent {
778			if _, ok := seen[k]; ok {
779				continue
780			}
781			touched = append(touched, ringEntryKind{key: k, seq: endWM, delete: true})
782		}
783		sort.Slice(touched, func(i, j int) bool { return touched[i].key < touched[j].key })
784		return touched
785	}
786	
787	// writeIncrementalRing streams one ring in bounded chunks, fully syncs it in
788	// the staging directory and links it into place atomically (link fails
789	// rather than overwrite when another export advanced the chain). The chain
790	// directory is forced afterwards.
791	func writeIncrementalRing(chainDir string, hdr ringHeader, anchor backupAnchor, touched []ringEntryKind) error {
792		final := ringName(hdr.index)
793	
794		// Refuse to build before staging anything if another ring of this index
795		// already exists: a concurrent export appended first.
796		if _, err := os.Stat(filepath.Join(chainDir, final)); err == nil {
797			return errBadBackup
798		} else if !errors.Is(err, os.ErrNotExist) {
799			return err
800		}
801	
802		stage := filepath.Join(chainDir, incrStageDir)
803		if err := os.MkdirAll(stage, 0o700); err != nil {
804			if errors.Is(err, os.ErrExist) {
805				// A non-directory entry occupies the staging name: foreign debris,
806				// never a usable chain.
807				return errBadBackup
808			}
809			return err
810		}
811		tmpPath := filepath.Join(stage, final)
812		cleanup := func() { os.RemoveAll(stage) }
813	
814		tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
815		if err != nil {
816			if errors.Is(err, os.ErrExist) {
817				// Another export is already staging this ring: this store cannot
818				// also append it.
819				cleanup()
820				return errBadBackup
821			}
822			cleanup()
823			return err
824		}
825		fail := func(err error) error {
826			tmp.Close()
827			cleanup()
828			return err
829		}
830	
831		w := bufio.NewWriter(tmp)
832		hf := crc32.NewIEEE()
833		// write bytes to the ring, advancing the whole-file CRC for every byte.
834		write := func(b []byte) error {
835			if _, err := w.Write(b); err != nil {
836				return err
837			}
838			hf.Write(b)
839			return nil
840		}
841	
842		segCount := uint32(0)
843		if len(touched) > 0 {
844			segCount = uint32((len(touched) + backupEntriesPerSegment - 1) / backupEntriesPerSegment)
845		}
846	
847		head := make([]byte, incrRingHeaderSize)
848		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
849		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
850		binary.LittleEndian.PutUint32(head[8:12], hdr.index)
851		binary.LittleEndian.PutUint32(head[12:16], hdr.prevLink)
852		binary.LittleEndian.PutUint64(head[16:24], hdr.startWM)
853		binary.LittleEndian.PutUint64(head[24:32], hdr.endWM)
854		binary.LittleEndian.PutUint64(head[32:40], hdr.snaps)
855		binary.LittleEndian.PutUint32(head[40:44], segCount)
856		if err := write(head); err != nil {
857			return fail(err)
858		}
859	
860		ehdr := make([]byte, checkpointEntrySize)
861		var segChain uint32
862		var cumulative uint64
863		for seg := uint32(0); seg < segCount; seg++ {
864			start := int(seg) * backupEntriesPerSegment
865			stop := start + backupEntriesPerSegment
866			if stop > len(touched) {
867				stop = len(touched)
868			}
869			chunk := touched[start:stop]
870	
871			hs := crc32.NewIEEE()
872			sh := make([]byte, incrSegHeaderSize)
873			binary.LittleEndian.PutUint32(sh[0:4], backupMagic)
874			binary.LittleEndian.PutUint64(sh[4:12], hdr.startWM)
875			binary.LittleEndian.PutUint64(sh[12:20], hdr.endWM)
876			binary.LittleEndian.PutUint32(sh[20:24], hdr.index)
877			binary.LittleEndian.PutUint32(sh[24:28], seg)
878			// cumulative is filled after the chunk is encoded; entries cannot be
879			// dropped, so the count equals the chunk length.
880			cumulative += uint64(len(chunk))
881			binary.LittleEndian.PutUint32(sh[28:32], uint32(len(chunk)))
882			binary.LittleEndian.PutUint64(sh[32:40], cumulative)
883			if err := write(sh); err != nil {
884				return fail(err)
885			}
886			hs.Write(sh)
887	
888			writeEntry := func(flag byte, key string, value []byte, seq uint64) error {
889				if len(key) > maxRecord || len(value) > maxRecord {
890					return errors.New("snapshot: incremental entry too large")
891				}
892				if flag == ckptFlagPut {
893					ehdr[0] = ckptFlagPut
894				} else {
895					ehdr[0] = ckptFlagDelete
896				}
897				binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(key)))
898				binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(value)))
899				binary.LittleEndian.PutUint64(ehdr[9:17], seq)
900				if err := write(ehdr); err != nil {
901					return err
902				}
903				hs.Write(ehdr)
904				if _, err := io.WriteString(w, key); err != nil {
905					return err
906				}
907				hf.Write([]byte(key))
908				hs.Write([]byte(key))
909				if len(value) > 0 {
910					if err := write(value); err != nil {
911						return err
912					}
913					hs.Write(value)
914				}
915				return nil
916			}
917	
918			for _, e := range chunk {
919				if e.delete {
920					if err := writeEntry(ckptFlagDelete, e.key, nil, e.seq); err != nil {
921						return fail(err)
922					}
923				} else {
924					n := anchor.view.lookup(e.key)
925					if n == nil || !n.present || n.seq != e.seq {
926						return fail(errBadBackup)
927					}
928					if err := writeEntry(ckptFlagPut, e.key, cloneBytes(n.value), e.seq); err != nil {
929						return fail(err)
930					}
931				}
932			}
933	
934			var sc [crcSize]byte
935			binary.LittleEndian.PutUint32(sc[:], hs.Sum32())
936			if err := write(sc[:]); err != nil {
937				return fail(err)
938			}
939			segChain = crc32.Update(segChain, crc32.IEEETable, sc[:])
940		}
941	
942		foot := make([]byte, incrFooterSize)
943		binary.LittleEndian.PutUint64(foot[0:8], cumulative)
944		binary.LittleEndian.PutUint32(foot[8:12], segCount)
945		binary.LittleEndian.PutUint32(foot[12:16], segChain)
946		if err := write(foot); err != nil {
947			return fail(err)
948		}
949		var fc [crcSize]byte
950		binary.LittleEndian.PutUint32(fc[:], hf.Sum32())
951		// Flush every buffered byte before appending the terminal CRC: writing it
952		// through the raw file while the bufio writer still held content would
953		// place the CRC at offset 0 and the buffered body after it.
954		if err := w.Flush(); err != nil {
955			return fail(err)
956		}
957		if _, err := tmp.Write(fc[:]); err != nil {
958			return fail(err)
959		}
960		if err := tmp.Sync(); err != nil {
961			return fail(err)
962		}
963		if err := tmp.Close(); err != nil {
964			cleanup()
965			return err
966		}
967	
968		// Promote with link(2): it never overwrites, so a concurrent export cannot
969		// be clobbered, and the ring appears whole or not at all.
970		if err := os.Link(tmpPath, filepath.Join(chainDir, final)); err != nil {
971			if errors.Is(err, os.ErrExist) {
972				cleanup()
973				return errBadBackup
974			}
975			cleanup()
976			return err
977		}
978		if err := syncDirectory(chainDir); err != nil {
979			return err
980		}
981		cleanup()
982		return syncDirectory(chainDir)
983	}
984

