1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"hash/crc32"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12	)
13	
14	// Hot backup and restore.
15	//
16	// A backup exports the store's complete committed state at one fixed commit
17	// watermark as a portable, segmented artifact. The export anchors to the
18	// current view and then streams its terminal entries into self-describing,
19	// checksummed segments without holding the store's write lock: writes,
20	// deletes, batch commits, snapshots, cursor paging, checkpoints and
21	// compactions proceed concurrently and never block on the disk writes the
22	// backup performs. Reads keep hitting memory exactly as before.
23	//
24	// Artifact layout, inside the output directory:
25	//
26	//	backup.tmp/                staging area while an export runs
27	//	segment-XXXXX.dat          finished segments, promoted one at a time
28	//	manifest.dat               present only when the whole export finished
29	//
30	// The artifact is complete if and only if manifest.dat is present, intact and
31	// agrees exactly with the segment files that exist; Restore rejects anything
32	// short of that wholesale with fs.ErrInvalid. A kill at any instant therefore
33	// leaves either the previous contents of the directory or one complete
34	// artifact; staging debris and an orphaned manifest temp are swept at the
35	// start of the next backup into that directory or the next Open of it, and
36	// the store being backed up is never touched.
37	//
38	// Segment file layout (all integers little-endian):
39	//
40	//	magic      uint32   backupMagic
41	//	version    uint32   backupVersion
42	//	watermark  uint64   highest commit sequence exported
43	//	snapshots  uint64   cumulative snapshot count at the export watermark
44	//	index      uint32   segment position, starting at 0
45	//	count      uint32   number of entries in this segment
46	//	cumulative uint64   cumulative live-entry count through this segment
47	//	entries    [count]entry
48	//	crc        uint32   IEEE CRC-32 of every preceding byte of the file
49	//
50	// One entry is a flags byte (0 = put, 1 = tombstone), a uint32 key length, a
51	// uint32 value length, the entry's commit sequence (uint64), the key, then
52	// the value. Entries are written in ascending key order; a put carries its
53	// value bytes, a tombstone carries none.
54	//
55	// The manifest repeats the artifact-level fields (magic, version, watermark,
56	// snapshots, total entry count, segment count) and one record per segment
57	// (its index, entry count, cumulative count and content CRC), terminated by
58	// an overall CRC. A segment is accepted only when its own CRC verifies and
59	// every field the manifest records about it matches: a missing segment, a
60	// truncated segment, a checksum mismatch, an unknown version or a manifest
61	// that disagrees with the files rejects the entire artifact.
62	const (
63		backupStageDir    = "backup.tmp"
64		backupManifest    = "manifest.dat"
65		backupManifestTmp = "manifest.dat.tmp"
66		backupSegmentPref = "segment-"
67		backupSegmentSufx = ".dat"
68	
69		backupMagic   uint32 = 0x42414b53 // bytes "SKAB"
70		backupVersion uint32 = 1
71	
72		// backupSegHeaderSize is magic, version, watermark, snapshots, index,
73		// count, cumulative.
74		backupSegHeaderSize = 4 + 4 + 8 + 8 + 4 + 4 + 8
75		// backupManifestSize is magic, version, watermark, snapshots, total
76		// entries and segment count; the terminal overall CRC follows the
77		// per-segment records.
78		backupManifestSize = 4 + 4 + 8 + 8 + 8 + 4
79		// backupSegRecSize is one manifest per-segment record: index, count,
80		// cumulative, content CRC.
81		backupSegRecSize = 4 + 4 + 8 + 4
82		// backupEntriesPerSegment bounds how many entries one segment holds. The
83		// export streams entries a chunk this size and flushes a segment per
84		// chunk, so the whole keyspace is never copied out before hitting disk;
85		// only one chunk of values is resident at a time. It is a write-chunking
86		// target, not a format limit.
87		backupEntriesPerSegment = 4096
88		// backupMaxSegments is a sanity ceiling on the segment count a manifest
89		// may declare, bounding pre-allocation when reading an untrusted file.
90		backupMaxSegments = 1 << 20
91	)
92	
93	// backupAnchor is the fixed point-in-time state an export streams. It is
94	// captured under the store lock and is immutable afterwards: published views
95	// are never mutated, so the streaming that follows takes no lock and cannot
96	// observe commits made after the anchor.
97	type backupAnchor struct {
98		view      *view
99		watermark uint64 // highest commit sequence covered
100		snaps     uint64 // cumulative snapshot count covered
101	}
102	
103	// backupEntry is one terminal key state in export order.
104	type backupEntry struct {
105		key     string
106		value   []byte
107		seq     uint64
108		present bool
109	}
110	
111	// Backup exports the store's complete committed state into outDir as a
112	// portable, segmented backup anchored at the commit watermark current when
113	// Backup anchors. Writes and deletes committed after the anchor are not
114	// included and proceed concurrently without blocking; every lock-free read
115	// keeps hitting memory and is never held up by the export's disk writes.
116	//
117	// The export streams the keyspace in fixed-size segments and never copies the
118	// whole keyspace out before writing it. It is all-or-nothing: segment files
119	// are built and synced in a staging directory and promoted one at a time; the
120	// manifest is written last and only becomes visible once every segment it
121	// names is durable. A process killed at any point leaves no half artifact in
122	// outDir — staging debris is swept at the start of the next Backup there (or
123	// the next Open of that directory) and never affects the backed-up store.
124	//
125	// A path that does not exist or is not a directory, or a directory that
126	// already holds a complete or partial artifact or any unrelated entry, is
127	// rejected with an error wrapping fs.ErrInvalid. Backup on a closed store
128	// returns an error wrapping fs.ErrClosed.
129	func (s *Store) Backup(outDir string) error {
130		if s.closed.Load() {
131			return errStoreClosed
132		}
133		if outDir == "" {
134			return errBadBackup
135		}
136	
137		// Prepare the output directory and clear debris from an export killed
138		// mid-run, before touching the store. A finished artifact or any foreign
139		// entry is never overwritten.
140		info, err := os.Stat(outDir)
141		if err != nil {
142			if !errors.Is(err, os.ErrNotExist) {
143				return err
144			}
145			if err := os.MkdirAll(outDir, 0o700); err != nil {
146				return err
147			}
148		} else if !info.IsDir() {
149			return errBadBackup
150		}
151		if err := prepareBackupDir(outDir); err != nil {
152			return err
153		}
154	
155		// Anchor at one fixed watermark. This is the only moment the export takes
156		// the write lock; everything after it streams from an immutable view.
157		s.mu.Lock()
158		if s.closed.Load() {
159			s.mu.Unlock()
160			return errStoreClosed
161		}
162		anchor := backupAnchor{
163			view:      s.current.Load(),
164			watermark: s.nextSeq,
165			snaps:     s.snapshots.Load(),
166		}
167		s.mu.Unlock()
168	
169		return writeBackup(outDir, anchor)
170	}
171	
172	// prepareBackupDir makes outDir an empty target for a fresh artifact: it
173	// removes staging debris and orphaned files from an interrupted export and
174	// refuses to overwrite a finished artifact or any unrelated entry.
175	func prepareBackupDir(outDir string) error {
176		entries, err := os.ReadDir(outDir)
177		if err != nil {
178			return err
179		}
180		for _, e := range entries {
181			name := e.Name()
182			switch {
183			case e.IsDir() && (name == backupStageDir || name == incrStageDir):
184				// staging debris, removed below
185			case !e.IsDir() && (isBackupSegmentName(name) || isBackupRingName(name) || name == backupManifestTmp):
186				// orphaned by a kill, removed below
187			default:
188				return errBadBackup
189			}
190		}
191		for _, stage := range []string{backupStageDir, incrStageDir} {
192			if err := os.RemoveAll(filepath.Join(outDir, stage)); err != nil {
193				return err
194			}
195		}
196		for _, e := range entries {
197			if e.IsDir() {
198				continue
199			}
200			name := e.Name()
201			if isBackupSegmentName(name) || isBackupRingName(name) || name == backupManifestTmp {
202				if err := os.Remove(filepath.Join(outDir, name)); err != nil &&
203					!errors.Is(err, os.ErrNotExist) {
204					return err
205				}
206			}
207		}
208		return syncDirectory(outDir)
209	}
210	
211	// isBackupRingName reports whether name is a finished incremental ring file.
212	func isBackupRingName(name string) bool {
213		_, ok := parseRingIndex(name)
214		return ok
215	}
216	
217	// isBackupSegmentName reports whether name is a finished segment file name.
218	func isBackupSegmentName(name string) bool {
219		return len(name) > len(backupSegmentPref)+len(backupSegmentSufx) &&
220			name[:len(backupSegmentPref)] == backupSegmentPref &&
221			name[len(name)-len(backupSegmentSufx):] == backupSegmentSufx
222	}
223	
224	// parseSegmentIndex is the inverse of segmentName. ok is false for names that
225	// are not well-formed finished segment files.
226	func parseSegmentIndex(name string) (uint32, bool) {
227		const body = "0000000000"
228		mid := len(backupSegmentPref) + len(body)
229		if len(name) != mid+len(backupSegmentSufx) ||
230			name[:len(backupSegmentPref)] != backupSegmentPref ||
231			name[mid:] != backupSegmentSufx {
232			return 0, false
233		}
234		var n uint32
235		for i := len(backupSegmentPref); i < mid; i++ {
236			c := name[i]
237			if c < '0' || c > '9' {
238				return 0, false
239			}
240			n = n*10 + uint32(c-'0')
241		}
242		return n, true
243	}
244	
245	// segmentName renders a segment index as a fixed-width, zero-padded name.
246	func segmentName(index uint32) string {
247		const digits = "0123456789"
248		buf := make([]byte, 10)
249		n := index
250		for i := len(buf) - 1; i >= 0; i-- {
251			buf[i] = digits[n%10]
252			n /= 10
253		}
254		return backupSegmentPref + string(buf) + backupSegmentSufx
255	}
256	
257	// writeBackup streams the anchor's terminal entries into segments and finishes
258	// with the manifest. It holds no store lock: the anchored view is immutable.
259	func writeBackup(outDir string, anchor backupAnchor) error {
260		stage := filepath.Join(outDir, backupStageDir)
261		if err := os.MkdirAll(stage, 0o700); err != nil {
262			return err
263		}
264		cleanup := func() {
265			os.RemoveAll(stage)
266			if entries, rerr := os.ReadDir(outDir); rerr == nil {
267				for _, e := range entries {
268					if !e.IsDir() && isBackupSegmentName(e.Name()) {
269						os.Remove(filepath.Join(outDir, e.Name()))
270					}
271				}
272				os.Remove(filepath.Join(outDir, backupManifestTmp))
273			}
274			_ = syncDirectory(outDir)
275		}
276	
277		// One index pass over the immutable view yields the sorted live keys.
278		// Only present keys are exported: a restore rebuilds a fresh log with no
279		// older history to mask, so deleted keys are simply absent — exactly as a
280		// compaction drops them. This keeps the artifact proportional to live
281		// data, not the cumulative set of every key ever touched. Values are not
282		// collected here; they are read and written a chunk at a time below, so the
283		// whole keyspace is never resident before hitting disk.
284		var keys []string
285		anchor.view.rangeEach(func(k string, n *node) bool {
286			if n.present {
287				keys = append(keys, k)
288			}
289			return true
290		})
291		sort.Strings(keys)
292	
293		var segments []manifestSegment
294		var total uint64
295		var index uint32
296	
297		for start := 0; start < len(keys); start += backupEntriesPerSegment {
298			stop := start + backupEntriesPerSegment
299			if stop > len(keys) {
300				stop = len(keys)
301			}
302			entries := make([]backupEntry, 0, stop-start)
303			for _, k := range keys[start:stop] {
304				n := anchor.view.lookup(k)
305				if n == nil || !n.present {
306					continue
307				}
308				entries = append(entries, backupEntry{
309					key:     k,
310					seq:     n.seq,
311					present: true,
312					value:   cloneBytes(n.value),
313				})
314			}
315			cumulative := total + uint64(len(entries))
316			crc, err := writeSegment(stage, index, anchor, cumulative, entries)
317			if err != nil {
318				cleanup()
319				return err
320			}
321			// Promote the fully synced segment out of staging. A crash exposes at
322			// worst a finished segment without the manifest, which is pure debris;
323			// it never exposes a partial file under a finished name.
324			if err := os.Rename(
325				filepath.Join(stage, segmentName(index)),
326				filepath.Join(outDir, segmentName(index)),
327			); err != nil {
328				cleanup()
329				return err
330			}
331			if err := syncDirectory(outDir); err != nil {
332				cleanup()
333				return err
334			}
335			segments = append(segments, manifestSegment{
336				index:      index,
337				count:      uint32(len(entries)),
338				cumulative: cumulative,
339				crc:        crc,
340			})
341			total = cumulative
342			index++
343		}
344	
345		// The manifest is the commit point: it names exactly the durable segment
346		// set and carries the artifact metadata. Building it last makes the whole
347		// export all-or-nothing.
348		if err := writeManifest(outDir, stage, anchor, total, segments); err != nil {
349			cleanup()
350			return err
351		}
352		if err := os.RemoveAll(stage); err != nil {
353			return err
354		}
355		return syncDirectory(outDir)
356	}
357	
358	// writeSegment serializes one fully synced segment file in dir and returns the
359	// content CRC written into its terminal checksum field.
360	func writeSegment(dir string, index uint32, anchor backupAnchor, cumulative uint64, entries []backupEntry) (uint32, error) {
361		path := filepath.Join(dir, segmentName(index))
362		tmp, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
363		if err != nil {
364			return 0, err
365		}
366		fail := func(err error) (uint32, error) {
367			tmp.Close()
368			os.Remove(path)
369			return 0, err
370		}
371	
372		w := bufio.NewWriter(tmp)
373		head := make([]byte, backupSegHeaderSize)
374		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
375		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
376		binary.LittleEndian.PutUint64(head[8:16], anchor.watermark)
377		binary.LittleEndian.PutUint64(head[16:24], anchor.snaps)
378		binary.LittleEndian.PutUint32(head[24:28], index)
379		binary.LittleEndian.PutUint32(head[28:32], uint32(len(entries)))
380		binary.LittleEndian.PutUint64(head[32:40], cumulative)
381	
382		h := crc32.NewIEEE()
383		if _, err := w.Write(head); err != nil {
384			return fail(err)
385		}
386		h.Write(head)
387	
388		ehdr := make([]byte, checkpointEntrySize)
389		for _, e := range entries {
390			if len(e.key) > maxRecord || len(e.value) > maxRecord {
391				return fail(errors.New("snapshot: backup entry too large"))
392			}
393			if e.present {
394				ehdr[0] = ckptFlagPut
395			} else {
396				ehdr[0] = ckptFlagDelete
397			}
398			binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(e.key)))
399			binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(e.value)))
400			binary.LittleEndian.PutUint64(ehdr[9:17], e.seq)
401			if _, err := w.Write(ehdr); err != nil {
402				return fail(err)
403			}
404			h.Write(ehdr)
405			if _, err := io.WriteString(w, e.key); err != nil {
406				return fail(err)
407			}
408			h.Write([]byte(e.key))
409			if len(e.value) > 0 {
410				if _, err := w.Write(e.value); err != nil {
411					return fail(err)
412				}
413				h.Write(e.value)
414			}
415		}
416	
417		crc := h.Sum32()
418		var crcb [crcSize]byte
419		binary.LittleEndian.PutUint32(crcb[:], crc)
420		if _, err := w.Write(crcb[:]); err != nil {
421			return fail(err)
422		}
423		if err := w.Flush(); err != nil {
424			return fail(err)
425		}
426		if err := tmp.Sync(); err != nil {
427			return fail(err)
428		}
429		if err := tmp.Close(); err != nil {
430			os.Remove(path)
431			return 0, err
432		}
433		return crc, nil
434	}
435	
436	// manifestInfo is the validated content of manifest.dat.
437	type manifestInfo struct {
438		watermark uint64
439		snaps     uint64
440		total     uint64
441		crc       uint32 // manifest terminal content CRC; the first ring links to it
442		segments  []manifestSegment
443	}
444	
445	// manifestSegment describes one segment the manifest names.
446	type manifestSegment struct {
447		index      uint32
448		count      uint32
449		cumulative uint64
450		crc        uint32
451	}
452	
453	// writeManifest builds and durably installs the manifest, the export's commit
454	// point. It is written under a temp name in the staging directory, synced,
455	// renamed into outDir and followed by a directory force.
456	func writeManifest(outDir, stage string, anchor backupAnchor, total uint64, segs []manifestSegment) error {
457		if err := os.MkdirAll(stage, 0o700); err != nil {
458			return err
459		}
460		tmpPath := filepath.Join(stage, backupManifestTmp)
461		tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
462		if err != nil {
463			return err
464		}
465		fail := func(err error) error {
466			tmp.Close()
467			os.Remove(tmpPath)
468			return err
469		}
470	
471		w := bufio.NewWriter(tmp)
472		head := make([]byte, backupManifestSize)
473		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
474		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
475		binary.LittleEndian.PutUint64(head[8:16], anchor.watermark)
476		binary.LittleEndian.PutUint64(head[16:24], anchor.snaps)
477		binary.LittleEndian.PutUint64(head[24:32], total)
478		binary.LittleEndian.PutUint32(head[32:36], uint32(len(segs)))
479		h := crc32.NewIEEE()
480		if _, err := w.Write(head); err != nil {
481			return fail(err)
482		}
483		h.Write(head)
484	
485		rec := make([]byte, backupSegRecSize)
486		for _, s := range segs {
487			binary.LittleEndian.PutUint32(rec[0:4], s.index)
488			binary.LittleEndian.PutUint32(rec[4:8], s.count)
489			binary.LittleEndian.PutUint64(rec[8:16], s.cumulative)
490			binary.LittleEndian.PutUint32(rec[16:20], s.crc)
491			if _, err := w.Write(rec); err != nil {
492				return fail(err)
493			}
494			h.Write(rec)
495		}
496		var crcb [crcSize]byte
497		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
498		if _, err := w.Write(crcb[:]); err != nil {
499			return fail(err)
500		}
501		if err := w.Flush(); err != nil {
502			return fail(err)
503		}
504		if err := tmp.Sync(); err != nil {
505			return fail(err)
506		}
507		if err := tmp.Close(); err != nil {
508			os.Remove(tmpPath)
509			return err
510		}
511		if err := os.Rename(tmpPath, filepath.Join(outDir, backupManifest)); err != nil {
512			os.Remove(tmpPath)
513			return err
514		}
515		return syncDirectory(outDir)
516	}
517	
518	// sweepBackupDebris removes temporary files an export killed before its commit
519	// point can leave in a directory: the full and incremental staging
520	// directories and a manifest temp. Finished segment and ring files are left
521	// here (only the next backup into that directory reclaims them); the manifest,
522	// when present, is never touched.
523	func sweepBackupDebris(dir string) error {
524		for _, stage := range []string{backupStageDir, incrStageDir} {
525			if err := os.RemoveAll(filepath.Join(dir, stage)); err != nil &&
526				!errors.Is(err, os.ErrNotExist) {
527				return err
528			}
529		}
530		if err := os.Remove(filepath.Join(dir, backupManifestTmp)); err != nil &&
531			!errors.Is(err, os.ErrNotExist) {
532			return err
533		}
534		return nil
535	}
536

