14	// Restore loads a backup artifact produced by Store.Backup from backupDir and
15	// installs a ready-to-open store into targetDir, returning it already open.
16	// The restored directory, once reopened, is byte-for-byte the complete
17	// committed state at the export watermark: a full replay from it yields the
18	// same terminal state the backup captured, and the cumulative snapshot count
19	// is preserved exactly.
20	//
21	// The artifact is validated as one whole before anything is installed: a
22	// missing segment, a truncated segment, a checksum mismatch, an unknown format
23	// version or a manifest that disagrees with the files rejects the entire
24	// backup with an error wrapping fs.ErrInvalid, and no target is created.
25	//
26	// Installation is all-or-nothing: the new store is fully built and synced in a
27	// temporary sibling directory and only then renamed onto targetDir. A process
28	// killed at any instant leaves either the previous target or one complete
29	// store; a half-built temporary directory is swept by the next Restore or the
30	// next Open of the related directory.
31	//
32	// A backup path that does not exist or is not a directory is rejected with an
33	// error wrapping fs.ErrInvalid. A target path that already exists and is not
34	// empty (including a regular file) is rejected the same way.
35	func Restore(backupDir, targetDir string) (*Store, error) {
36		if backupDir == "" || targetDir == "" {
37			return nil, errBadBackup
38		}
39	
40		// The artifact itself must be an existing directory whose only entries are
41		// the manifest and the segments it names.
42		binfo, err := os.Stat(backupDir)
43		if err != nil {
44			return nil, errBadBackup
45		}
46		if !binfo.IsDir() {
47			return nil, errBadBackup
48		}
49	
50		// When incremental rings extend the head artifact, the whole chain is
51		// validated up front (missing rings, broken links, discontinuous
52		// watermarks, truncation, checksum failures and unknown versions reject
53		// the entire directory); a head-only artifact keeps its original path.
54		hasRings, err := dirHasRings(backupDir)
55		if err != nil {
56			return nil, err
57		}
58		var chain artifactInfo
59		var manifest manifestInfo
60		if hasRings {
61			chain, err = validateBackupChain(backupDir)
62			if err != nil {
63				return nil, err
64			}
65			manifest = chain.head
66		} else {
67			manifest, err = loadBackupManifest(backupDir)
68			if err != nil {
69				// Content defects already wrap fs.ErrInvalid; an underlying read
70				// failure passes through unchanged.
71				return nil, err
72			}
73			if err := verifyBackupFileSet(backupDir, manifest.segments); err != nil {
74				return nil, err
75			}
76		}
77	
78		// The target must be absent or an empty directory.
79		if err := checkRestoreTarget(targetDir); err != nil {
80			return nil, err
81		}
82	
83		// Build the complete store in a temporary sibling so a kill never exposes
84		// a half-installed target. The sibling lives next to the target so the
85		// final rename is atomic on one filesystem.
86		parent := filepath.Dir(targetDir)
87		if err := os.MkdirAll(parent, 0o700); err != nil {
88			return nil, err
89		}
90		stage, err := os.MkdirTemp(parent, filepath.Base(targetDir)+".restore-*")
91		if err != nil {
92			return nil, err
93		}
94		installed := false
95		defer func() {
96			if !installed {
97				_ = os.RemoveAll(stage)
98			}
99		}()
100	
101		if hasRings {
102			err = buildChainRestoredStore(stage, backupDir, chain)
103		} else {
104			err = buildRestoredStore(stage, backupDir, manifest)
105		}
106		if err != nil {
107			// Artifact validation failures already wrap fs.ErrInvalid; a genuine
108			// write failure is reported as-is rather than mislabeled invalid.
109			return nil, err
110		}
111	
112		if err := installRestoreTarget(stage, targetDir); err != nil {
113			return nil, err
114		}
115		installed = true
116	
117		return Open(targetDir)
118	}
