120	// checkRestoreTarget accepts an absent path or an existing empty directory;
121	// anything else (a regular file, symlink, or non-empty directory) is invalid.
122	func checkRestoreTarget(target string) error {
123		info, err := os.Stat(target)
124		if err != nil {
125			if errors.Is(err, os.ErrNotExist) {
126				return nil
127			}
128			return err
129		}
130		if !info.IsDir() {
131			return errBadBackup
132		}
133		entries, err := os.ReadDir(target)
134		if err != nil {
135			return err
136		}
137		if len(entries) != 0 {
138			return errBadBackup
139		}
140		return nil
141	}
142	
143	// verifyBackupFileSet rejects any entry besides the manifest and exactly the
144	// dense segment set the manifest names, and rejects gaps or extras.
145	func verifyBackupFileSet(backupDir string, segs []manifestSegment) error {
146		entries, err := os.ReadDir(backupDir)
147		if err != nil {
148			return err
149		}
150		want := make(map[uint32]bool, len(segs))
151		for _, s := range segs {
152			if s.index != uint32(len(want)) {
153				return errBadBackup // dense, ordered 0..n-1
154			}
155			want[s.index] = true
156		}
157		got := make(map[uint32]bool, len(segs))
158		for _, e := range entries {
159			if e.IsDir() {
160				return errBadBackup // no staging or foreign directory in a valid artifact
161			}
162			name := e.Name()
163			if name == backupManifest || name == backupManifestTmp {
164				if name == backupManifestTmp {
165					return errBadBackup // an unfinished manifest means an unfinished export
166				}
167				continue
168			}
169			idx, ok := parseSegmentIndex(name)
170			if !ok {
171				return errBadBackup // foreign file
172			}
173			if !want[idx] {
174				return errBadBackup // extra segment
175			}
176			if got[idx] {
177				return errBadBackup
178			}
179			got[idx] = true
180		}
181		if len(got) != len(want) {
182			return errBadBackup // a named segment is missing
183		}
184		return nil
185	}
186	
187	// readFull reads exactly len(buf) bytes from r; a short read (a truncated
188	// artifact) is reported as errBadBackup rather than io.ErrUnexpectedEOF,
189	// while any other read failure passes through.
190	func readFull(r io.Reader, buf []byte) error {
191		if _, err := io.ReadFull(r, buf); err != nil {
192			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
193				return errBadBackup
194			}
195			return err
196		}
197		return nil
198	}
199	
200	// loadBackupManifest reads and fully validates manifest.dat.
201	func loadBackupManifest(backupDir string) (manifestInfo, error) {
202		var zero manifestInfo
203		f, err := os.Open(filepath.Join(backupDir, backupManifest))
204		if err != nil {
205			// A missing manifest means the export never reached its commit point:
206			// the artifact is incomplete, not a transient I/O failure.
207			if errors.Is(err, os.ErrNotExist) {
208				return zero, errBadBackup
209			}
210			return zero, err
211		}
212		defer f.Close()
213	
214		r := bufio.NewReader(f)
215		head := make([]byte, backupManifestSize)
216		if err := readFull(r, head); err != nil {
217			return zero, err
218		}
219		h := crc32.NewIEEE()
220		h.Write(head)
221	
222		magic := binary.LittleEndian.Uint32(head[0:4])
223		version := binary.LittleEndian.Uint32(head[4:8])
224		if magic != backupMagic || version != backupVersion {
225			return zero, errBadBackup
226		}
227		info := manifestInfo{
228			watermark: binary.LittleEndian.Uint64(head[8:16]),
229			snaps:     binary.LittleEndian.Uint64(head[16:24]),
230			total:     binary.LittleEndian.Uint64(head[24:32]),
231		}
232		n := binary.LittleEndian.Uint32(head[32:36])
233		// Every segment carries at least one entry, so the segment count never
234		// exceeds the entry total; an empty artifact has n == 0 and total == 0.
235		// The absolute cap only guards the pre-allocation against a forged count;
236		// the record loop rejects an artifact that does not actually contain them.
237		if uint64(n) > info.total || n > backupMaxSegments {
238			return zero, errBadBackup
239		}
240	
241		rec := make([]byte, backupSegRecSize)
242		var cumulative uint64
243		info.segments = make([]manifestSegment, 0, n)
244		for i := uint32(0); i < n; i++ {
245			if err := readFull(r, rec); err != nil {
246				return zero, err
247			}
248			h.Write(rec)
249			s := manifestSegment{
250				index:      binary.LittleEndian.Uint32(rec[0:4]),
251				count:      binary.LittleEndian.Uint32(rec[4:8]),
252				cumulative: binary.LittleEndian.Uint64(rec[8:16]),
253				crc:        binary.LittleEndian.Uint32(rec[16:20]),
254			}
255			if s.index != i {
256				return zero, errBadBackup
257			}
258			cumulative += uint64(s.count)
259			if s.cumulative != cumulative || s.count == 0 {
260				return zero, errBadBackup
261			}
262			info.segments = append(info.segments, s)
263		}
264		if cumulative != info.total {
265			return zero, errBadBackup
266		}
267	
268		var crcb [crcSize]byte
269		if err := readFull(r, crcb[:]); err != nil {
270			return zero, err
271		}
272		if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
273			return zero, errBadBackup
274		}
275		info.crc = binary.LittleEndian.Uint32(crcb[:])
276		if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
277			return zero, errBadBackup // trailing bytes, or an underlying read error
278		}
279		return info, nil
280	}
281	
282	// buildRestoredStore streams every named segment into a fresh wal.log in the
283	// staging directory, validating each segment as it reads. The result is a WAL
284	// whose full replay reproduces the exported terminal state (one terminal
285	// frame per key, the same shape a compaction writes), followed by the snapshot
286	// count meta. Nothing is installed until this whole step succeeds.
287	func buildRestoredStore(stage, backupDir string, info manifestInfo) error {
288		wf, err := os.OpenFile(filepath.Join(stage, walName), os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
289		if err != nil {
290			return err
291		}
292		fail := func(err error) error {
293			wf.Close()
294			return err
295		}
296		l := &walWriter{f: wf, w: bufio.NewWriter(wf)}
297	
298		var seen uint64
299		var lastKey string
300		haveKeys := false
301	
302		for _, seg := range info.segments {
303			f, err := os.Open(filepath.Join(backupDir, segmentName(seg.index)))
304			if err != nil {
305				return fail(err)
306			}
307			r := bufio.NewReader(f)
308			hdr := make([]byte, backupSegHeaderSize)
309			if err := readFull(r, hdr); err != nil {
310				f.Close()
311				return fail(err)
312			}
313			h := crc32.NewIEEE()
314			h.Write(hdr)
315	
316			magic := binary.LittleEndian.Uint32(hdr[0:4])
317			version := binary.LittleEndian.Uint32(hdr[4:8])
318			watermark := binary.LittleEndian.Uint64(hdr[8:16])
319			snaps := binary.LittleEndian.Uint64(hdr[16:24])
320			index := binary.LittleEndian.Uint32(hdr[24:28])
321			count := binary.LittleEndian.Uint32(hdr[28:32])
322			cumulative := binary.LittleEndian.Uint64(hdr[32:40])
323			if magic != backupMagic || version != backupVersion ||
324				watermark != info.watermark || snaps != info.snaps ||
325				index != seg.index || count != seg.count || cumulative != seg.cumulative {
326				f.Close()
327				return fail(errBadBackup)
328			}
329	
330			ehdr := make([]byte, checkpointEntrySize)
331			for i := uint32(0); i < count; i++ {
332				if err := readFull(r, ehdr); err != nil {
333					f.Close()
334					return fail(err)
335				}
336				h.Write(ehdr)
337				flag := ehdr[0]
338				keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
339				valLen := binary.LittleEndian.Uint32(ehdr[5:9])
340				seq := binary.LittleEndian.Uint64(ehdr[9:17])
341				if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
342					keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
343					(flag == ckptFlagDelete && valLen != 0) {
344					f.Close()
345					return fail(errBadBackup)
346				}
347				body := make([]byte, int(keyLen)+int(valLen))
348				if err := readFull(r, body); err != nil {
349					f.Close()
350					return fail(err)
351				}
352				h.Write(body)
353				key := string(body[:keyLen])
354				// Entries must be strictly ascending and unique across segments.
355				if haveKeys && key <= lastKey {
356					f.Close()
357					return fail(errBadBackup)
358				}
359				lastKey, haveKeys = key, true
360				value := body[keyLen:]
361				if flag == ckptFlagPut {
362					if err := l.encodeFrameSeq(opPutSeq, key, seq, value); err != nil {
363						f.Close()
364						return fail(err)
365					}
366				} else {
367					if err := l.encodeFrameSeq(opDeleteSeq, key, seq, nil); err != nil {
368						f.Close()
369						return fail(err)
370					}
371				}
372			}
373	
374			var crcb [crcSize]byte
375			if err := readFull(r, crcb[:]); err != nil {
376				f.Close()
377				return fail(err)
378			}
379			if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() ||
380				binary.LittleEndian.Uint32(crcb[:]) != seg.crc {
381				f.Close()
382				return fail(errBadBackup)
383			}
384			if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
385				f.Close()
386				return fail(errBadBackup)
387			}
388			f.Close()
389			seen += uint64(count)
390		}
391	
392		if seen != info.total {
393			return fail(errBadBackup)
394		}
395		if info.snaps > 0 {
396			var v [metaValueSize]byte
397			binary.LittleEndian.PutUint64(v[:], info.snaps)
398			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
399				return fail(err)
400			}
401		}
402		if err := l.w.Flush(); err != nil {
403			return fail(err)
404		}
405		if err := wf.Sync(); err != nil {
406			return fail(err)
407		}
408		if err := wf.Close(); err != nil {
409			return err
410		}
411		return syncDirectory(stage)
412	}
413	
414	// installRestoreTarget puts the fully built staging store onto target. The
415	// target is absent or empty: when it exists as an empty directory it is
416	// removed first, so the rename lands on no existing entry. A crash in between
417	// leaves either an empty/absent target or the complete store, never a partial
418	// one.
419	func installRestoreTarget(stage, target string) error {
420		if info, err := os.Stat(target); err == nil && info.IsDir() {
421			if err := os.Remove(target); err != nil {
422				return err
423			}
424			if err := syncDirectory(filepath.Dir(target)); err != nil {
425				return err
426			}
427		}
428		if err := os.Rename(stage, target); err != nil {
429			return err
430		}
431		return syncDirectory(filepath.Dir(target))
432	}
433	
434	// sweepRestoreDebris removes a half-built temporary restore directory left
435	// next to dir by a kill during Restore. It only ever removes the specific
436	// sibling names Restore creates.
437	func sweepRestoreDebris(dir string) {
438		parent := filepath.Dir(dir)
439		base := filepath.Base(dir)
440		entries, err := os.ReadDir(parent)
441		if err != nil {
442			return
443		}
444		fixed := base + ".restore.tmp"
445		for _, e := range entries {
446			name := e.Name()
447			if !e.IsDir() {
448				continue
449			}
450			if name == fixed || isRestoreTempName(name, base) {
451				_ = os.RemoveAll(filepath.Join(parent, name))
452			}
453		}
454		_ = syncDirectory(parent)
455	}
456	
457	// isRestoreTempName matches MkdirTemp's "<base>.restore-<random>" directories.
458	func isRestoreTempName(name, base string) bool {
459		prefix := base + ".restore-"
460		return len(name) > len(prefix) && name[:len(prefix)] == prefix
461	}
462	
463	// openBackupSweep cleans incomplete-backup debris found when opening a
464	// directory that was used as a backup output: a staging directory or manifest
465	// temp is always debris, and finished segments are debris only when the
466	// manifest that completes the artifact is absent. A complete artifact is left
467	// untouched.
468	func openBackupSweep(dir string) error {
469		if err := sweepBackupDebris(dir); err != nil {
470			return err
471		}
472		if _, err := os.Stat(filepath.Join(dir, backupManifest)); err == nil {
473			return nil // complete artifact; leave it in place
474		}
475		entries, err := os.ReadDir(dir)
476		if err != nil {
477			return err
478		}
479		var names []string
480		for _, e := range entries {
481			if e.IsDir() {
482				continue
483			}
484			if isBackupSegmentName(e.Name()) {
485				names = append(names, e.Name())
486			}
487			if _, ok := parseRingIndex(e.Name()); ok {
488				names = append(names, e.Name())
489			}
490		}
491		sort.Strings(names)
492		for _, name := range names {
493			if err := os.Remove(filepath.Join(dir, name)); err != nil &&
494				!errors.Is(err, os.ErrNotExist) {
495				return err
496			}
497		}
498		if len(names) > 0 {
499			return syncDirectory(dir)
500		}
501		return nil
502	}
