13	// Backup chain merge and old-ring retirement.
14	//
15	// MergeChain folds the chain head and the first n incremental rings into one
16	// new full head, so a chain that only ever grows can be compacted back down:
17	// the merged head is exactly the complete committed state at the n-th ring's
18	// watermark, with keys, values and the cumulative snapshot count preserved,
19	// and the rings it absorbed are deleted. The rings beyond n stay on the
20	// chain: their entries, watermarks and snapshot counts are unchanged, but
21	// they are re-linked and renumbered from 1 behind the new head, so the merged
22	// chain still validates as one whole — dense ring numbering, continuous
23	// watermarks, unbroken content-CRC links — and later BackupIncremental rings
24	// append to it exactly as before.
25	//
26	// The merge is fully streamed: the new head is built by a k-way merge over
27	// the old head segments and the first n rings (all key-sorted streams), and
28	// each surviving ring is re-encoded entry by entry. One bounded chunk of
29	// entries is resident at a time; the keyspace is never copied into memory
30	// wholesale before hitting disk.
31	//
32	// The new chain is assembled in a sibling staging directory
33	// ("<chain>.merge-new-*") next to the chain directory and validated as a
34	// whole chain before anything is committed. The commit swaps directories:
35	// the old chain is renamed aside ("<chain>.merge-old-*"), the staged chain is
36	// renamed onto the chain path, and only then is the old chain deleted. A kill
37	// at any instant therefore leaves either the old chain or the complete new
38	// chain at the chain path — at worst a staging or trash sibling remains, and
39	// a kill between the two renames is repaired by moving the whole old chain
40	// back. The debris is swept at the next merge, backup or incremental export
41	// into that directory, or the next open of a related directory.
42	//
43	// MergeChain never touches the backed-up store: it reads only chain
44	// artifacts, so writes, batch commits, snapshot open/close, cursor paging,
45	// checkpoints, compactions and lock-free reads proceed while it runs. It is
46	// serialized with incremental exports on the same store (and re-validates the
47	// chain tip before committing, so a chain advanced concurrently by another
48	// exporter rejects the merge wholesale rather than being clobbered by it).
49	const (
50		mergeStagePrefix = ".merge-new-"
51		mergeTrashPrefix = ".merge-old-"
52	)
53	
54	// errMergeAbort stops a stream goroutine when the merge that owns it fails;
55	// it is internal flow control and never escapes to a caller.
56	var errMergeAbort = errors.New("snapshot: merge stream aborted")
57	
58	// MergeChain merges the head of the backup chain in chainDir with its first
59	// rings incremental rings into one new full head and deletes the absorbed
60	// rings. The merged chain restores to exactly the state and cumulative
61	// snapshot count the original chain captured, keeps the remaining rings
62	// (renumbered from 1 behind the new head), passes the same whole-chain
63	// validation Restore performs, and accepts further BackupIncremental rings.
64	//
65	// The merge streams every artifact in bounded chunks and never holds the
66	// whole keyspace in memory. It runs entirely on the chain directory: the
67	// backed-up store is never modified, and live writes, batch commits,
68	// snapshots, cursors, checkpoints, compactions and reads proceed while it
69	// runs. The new chain is staged as a sibling directory, validated as a whole,
70	// and swapped into place so a kill at any instant leaves either the old chain
71	// or the complete new chain; leftover staging or trash siblings are swept at
72	// the next merge, backup or export into that directory or the next open of a
73	// related directory.
74	//
75	// A ring count below one or beyond the chain's ring count, a chain directory
76	// that is missing, not a directory, missing its head, or itself damaged (a
77	// missing ring, a broken link, a non-continuous watermark, truncation, a
78	// checksum failure or an unknown version), or a chain advanced concurrently
79	// during the merge, rejects the whole operation with an error wrapping
80	// fs.ErrInvalid and leaves the chain exactly as it was. MergeChain on a
81	// closed store returns an error wrapping fs.ErrClosed.
82	func (s *Store) MergeChain(chainDir string, rings int) error {
83		if s.closed.Load() {
84			return errStoreClosed
85		}
86		// Serialize with incremental exports driven by this store so a merge and
87		// an export never race to reshape the same chain. This lock is
88		// independent of mu: it is held across the merge's disk I/O and never
89		// blocks commits or lock-free reads.
90		s.backupMu.Lock()
91		defer s.backupMu.Unlock()
92		if s.closed.Load() {
93			return errStoreClosed
94		}
95		if chainDir == "" || rings < 1 {
96			return errBadBackup
97		}
98		// Repair or clear debris from a merge killed mid-commit before inspecting
99		// the chain, exactly as the next backup or open of the directory would.
100		sweepMergeDebris(chainDir)
101		info, err := os.Stat(chainDir)
102		if err != nil {
103			if errors.Is(err, os.ErrNotExist) {
104				return errBadBackup
105			}
106			return err
107		}
108		if !info.IsDir() {
109			return errBadBackup
110		}
111		// Clear staging debris from an export (full or incremental) killed
112		// mid-run; a manifest temp is pure debris as well.
113		for _, stage := range []string{incrStageDir, backupStageDir} {
114			if err := os.RemoveAll(filepath.Join(chainDir, stage)); err != nil {
115				return err
116			}
117		}
118		if err := os.Remove(filepath.Join(chainDir, backupManifestTmp)); err != nil &&
119			!errors.Is(err, os.ErrNotExist) {
120			return err
121		}
122	
123		art, err := validateBackupChain(chainDir)
124		if err != nil {
125			return err
126		}
127		if uint64(rings) > uint64(art.ringCount) {
128			return errBadBackup
129		}
130		n := rings
131	
132		// Stage the whole merged chain as a sibling of the chain directory so the
133		// final swap is a same-filesystem rename. The chain directory itself is
134		// not touched until the commit.
135		parent := filepath.Dir(chainDir)
136		base := filepath.Base(chainDir)
137		stage, err := os.MkdirTemp(parent, base+mergeStagePrefix)
138		if err != nil {
139			return err
140		}
141		committed := false
142		defer func() {
143			if !committed {
144				os.RemoveAll(stage)
145			}
146		}()
147	
148		// The new head covers the chain through ring n: its export watermark and
149		// cumulative snapshot count are exactly that ring's.
150		tip := art.ringSums[n-1]
151		anchor := backupAnchor{watermark: tip.endWM, snaps: tip.snaps}
152		segs, total, err := mergeChainHead(chainDir, stage, art, n, anchor)
153		if err != nil {
154			return err
155		}
156		if err := writeManifest(stage, stage, anchor, total, segs); err != nil {
157			return err
158		}
159		newHead, err := loadBackupManifest(stage)
160		if err != nil {
161			return err
162		}
163	
164		// Re-encode each surviving ring under its new 1-based index, linked to
165		// the artifact before it in the merged chain. Entries, watermarks and
166		// snapshot counts are carried over unchanged.
167		prevLink := newHead.crc
168		for j := n + 1; j <= int(art.ringCount); j++ {
169			old := art.ringSums[j-1]
170			prev := art.ringSums[j-2]
171			hdr := ringHeader{
172				index:    uint32(j - n),
173				prevLink: prevLink,
174				startWM:  prev.endWM,
175				endWM:    old.endWM,
176				snaps:    old.snaps,
177			}
178			exp := ringExpect{
179				index:    uint32(j),
180				prevLink: prev.fileCRC,
181				startWM:  prev.endWM,
182			}
183			prevLink, err = renumberRing(chainDir, stage, exp, hdr, old.segCount, old.total)
184			if err != nil {
185				return err
186			}
187		}
188	
189		// The staged chain must pass the same whole-chain validation Restore
190		// performs, and it must reach the same tip the original chain reached.
191		newArt, err := validateBackupChain(stage)
192		if err != nil {
193			return err
194		}
195		if newArt.ringCount != art.ringCount-uint32(n) ||
196			newArt.endWM != art.endWM || newArt.snaps != art.snaps {
197			return errBadBackup
198		}
199	
200		// Refuse to commit over a chain that moved since it was validated (an
201		// export or merge driven by another store): the merge is rejected
202		// wholesale and the chain keeps its newer shape.
203		again, err := validateBackupChain(chainDir)
204		if err != nil {
205			return err
206		}
207		if again.head.crc != art.head.crc || again.ringCount != art.ringCount ||
208			again.tipCRC != art.tipCRC || again.endWM != art.endWM ||
209			again.snaps != art.snaps {
210			return errBadBackup
211		}
212	
213		// Commit: move the old chain aside, move the staged chain onto the chain
214		// path, then delete the old chain. A kill before the first rename leaves
215		// the old chain; a kill between the renames leaves the whole old chain in
216		// the trash sibling (swept back into place next time); a kill after the
217		// second rename leaves the complete new chain.
218		trash, err := os.MkdirTemp(parent, base+mergeTrashPrefix)
219		if err != nil {
220			return err
221		}
222		if err := os.Remove(trash); err != nil {
223			return err
224		}
