229			// Best-effort rollback: the old chain is whole at trash.
230			if rb := os.Rename(trash, chainDir); rb == nil {
231				_ = syncDirectory(parent)
232			}
233			return err
234		}
235		committed = true
236		if err := syncDirectory(parent); err != nil {
237			return err
238		}
239		if err := os.RemoveAll(trash); err != nil {
240			return err
241		}
242		return syncDirectory(parent)
243	}
