		{"too many rings", chain, 3},
		{"empty path", "", 1},
		{"missing directory", filepath.Join(t.TempDir(), "nope"), 1},
		{"not a directory", plainFile, 1},
		{"no head", emptyDir, 1},
		{"no rings on chain", headOnly, 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			err := s.MergeChain(tc.dir, tc.rings)
			if err == nil {
